<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Activity, AppWindow, ArrowDownToLine, ArrowLeftToLine, ArrowUpToLine, Box, Cable, Check, CheckCheck, ChevronDown, Code2, Copy, Download, FilePlus2, FolderOpen, Grid2X2, Hash, Layers, ListFilter, Logs, MoreHorizontal, MousePointer2, Play, Plus, Redo2, Save, Settings2, ShieldCheck, Square, SquareStop, TextCursorInput, ToggleLeft, Trash2, Type, Undo2, Workflow, X, ChartNoAxesCombined, CircleDot, CircleHelp, Link2, Search } from 'lucide-vue-next'
import DesignCanvas from './components/DesignCanvas.vue'
import WidgetInspector from './components/WidgetInspector.vue'
import FlowEditor from './components/FlowEditor.vue'
import RuntimeView from './components/RuntimeView.vue'
import ResourcesPanel from './components/ResourcesPanel.vue'
import FButton from './components/fluent/FButton.vue'
import { useEditor, parseProject } from './lib/editor'
import { call, desktop, downloadProject, getEnvironment, pickFile, pickSave, useRuntime, validate } from './lib/backend'
import { clone, createNode, createWidget, demoProject, emptyProject, newId, widgetKinds, type Environment, type Project, type ValidationIssue } from './lib/model'
import { refreshAssets } from './lib/resources'
const editor = useEditor(demoProject()), runtime = useRuntime(), workspace = ref('design'), menuOpen = ref(false), paletteFilter = ref(''), activeLibrary = ref('widgets'), expanded = ref(true), projectPath = ref<string>(), environment = ref<Environment>(), issues = ref<ValidationIssue[]>([]), pending = ref(false), resources = ref<InstanceType<typeof ResourcesPanel>>(), fileInput = ref<HTMLInputElement>(), runtimeProject = ref<Project>(), toast = ref(''), toastError = ref(false), help = ref(false)
let toastTimeout: ReturnType<typeof setTimeout> | undefined
const icons: Record<string, any> = { Type, MousePointer2, TextCursorInput, Hash, ListFilter, ToggleLeft, CircleDot, Square, ChartNoAxesCombined, Logs }
const filteredWidgets = computed(() => widgetKinds.filter(w => w.label.includes(paletteFilter.value)))
function notify(message: string, error = false) { toast.value = message; toastError.value = error; if (toastTimeout) clearTimeout(toastTimeout); toastTimeout = setTimeout(() => toast.value = '', error ? 8000 : 3500) }
const report = (error: unknown) => notify(String(error).replace(/^Error:\s*/, ''), true)
async function perform(task: () => Promise<void>) { if (pending.value) return; pending.value = true; menuOpen.value = false; try { await task() } catch (error) { report(error) } finally { pending.value = false } }
async function saveProject(forcePath = false): Promise<boolean> {
  if (!desktop) { downloadProject(editor.project.value); editor.markSaved(); notify('项目 JSON 已下载'); return true }
  const path = !forcePath && projectPath.value ? projectPath.value : await pickSave(editor.project.value.name)
  if (!path) return false
  await call('save_project', { path, project: editor.project.value }); projectPath.value = path; editor.markSaved(); notify('项目已保存'); return true
}
function canReplace() { return !editor.dirty.value || window.confirm('当前项目有未保存修改，确定替换当前项目？') }
function newProject() { menuOpen.value = false; if (runtime.running.value || !canReplace()) return; editor.replace(emptyProject()); projectPath.value = undefined; issues.value = []; workspace.value = 'design' }
async function openProject() { if (!canReplace()) return; if (!desktop) { fileInput.value?.click(); return }; const path = await pickFile('project'); if (!path) return; const project = await call<Project>('open_project', { path }); editor.replace(parseProject(JSON.stringify(project))); projectPath.value = path; issues.value = []; workspace.value = 'design'; if (project.assets?.length) await refreshAssets(project); notify('项目已打开') }
async function browserOpen(event: Event) { const input = event.target as HTMLInputElement; try { const file = input.files?.[0]; if (file) { editor.replace(parseProject(await file.text())); projectPath.value = undefined; issues.value = []; workspace.value = 'design'; notify('项目已打开') } } catch (error) { report(error) } finally { input.value = '' } }
async function check() { if (!desktop) { parseProject(JSON.stringify(editor.project.value)); notify('项目格式检查通过；完整流程与代码校验请使用桌面版'); return }; issues.value = await validate(editor.project.value); resources.value?.showIssues(); notify(issues.value.some(i => i.severity === 'error') ? '项目存在问题，请查看检查面板' : '项目检查通过', issues.value.some(i => i.severity === 'error')) }
async function preview() { if (runtime.running.value) { await runtime.stop(); workspace.value = 'design'; runtimeProject.value = undefined; return }; if (!desktop) throw new Error('浏览器模式支持设计。请启动桌面版进行真实预览和设备通信。'); issues.value = await validate(editor.project.value); if (issues.value.some(i => i.severity === 'error')) { resources.value?.showIssues(); throw new Error('项目检查未通过，请先修复检查面板中的错误') }; runtimeProject.value = clone(editor.project.value); await runtime.start(runtimeProject.value); workspace.value = 'preview'; notify('预览已启动，设备连接由配置的操作打开') }
async function exportProject() { if (!(await saveProject())) return; const destination = await pickSave(editor.project.value.name, true); if (!destination) return; const result = await call<{ path: string; files: number; includesPython: boolean }>('export_project', { project: editor.project.value, destination }); notify(`运行包已生成：${result.path}${result.includesPython ? '（包含 Python）' : ''}`) }
async function importResource(kind: 'plugin' | 'python' | 'dependencies') { if (kind === 'dependencies' && !(await saveProject())) return; const path = await pickFile('directory'); if (!path) return; const result = await call<Project['python']>(kind === 'plugin' ? 'import_plugin' : kind === 'python' ? 'import_python_runtime' : 'import_python_dependencies', { path }); if (kind === 'dependencies' && result) { editor.mutate(project => project.python = result); await saveProject() }; await resources.value?.refresh(); environment.value = await getEnvironment(); notify('资源导入成功') }
async function importAsset() { if (!(await saveProject())) return; const path = await pickFile('asset'); if (!path) return; const result = await call<{ id: string; path: string }>('import_asset', { path }); editor.mutate(project => { project.assets ??= []; project.assets.push({ id: result.id, path: result.path }) }); await refreshAssets(editor.project.value); await saveProject(); notify('资源已导入，可在控件外观设置中选择图片或字体') }
function addPage() { const id = newId('page'); editor.mutate(p => p.pages.push({ id, name: `页面 ${p.pages.length + 1}`, widgets: [] })); editor.pageId.value = id; editor.selected.value = [] }
function removePage() { if (editor.project.value.pages.length < 2) { report('项目至少保留一个页面'); return }; editor.mutate(p => p.pages = p.pages.filter(page => page.id !== editor.pageId.value)); editor.pageId.value = editor.project.value.pages[0]!.id; editor.selected.value = [] }
function addSerialPanel(x = 64, y = 64) { let connection = editor.project.value.connections[0]; editor.mutate(p => { if (!connection) { connection = { id: newId('connection'), name: '串口连接', port: '', baudRate: 115200, dataBits: 8, stopBits: 1, parity: 'none', protocolId: 'demo-temperature', protocolVersion: '1.0.0', protocolConfig: {} }; p.connections.push(connection) }; const group = createWidget('group', x, y); group.props.text = '设备连接'; group.width = 360; group.height = 140; const widgets = [group]; for (const [index, kind] of ['connection.open', 'connection.close'].entries()) { const trigger = createNode('trigger.ui'), action = createNode(kind, { x: 340, y: 80 }); action.config.connectionId = connection!.id; const flowId = newId('flow'); p.flows.push({ id: flowId, name: index ? '关闭连接' : '打开连接', enabled: true, timeoutMs: 30000, nodes: [trigger, action], edges: [{ id: newId('edge'), source: trigger.id, sourcePort: 'out', target: action.id, targetPort: 'in' }] }); const button = createWidget('button', x + 20 + index * 160, y + 66); button.props.text = index ? '关闭连接' : '打开连接'; button.events.click = { kind: 'flow', flowId, entryNodeId: trigger.id }; widgets.push(button) }; editor.page.value.widgets.push(...widgets); editor.selected.value = widgets.map(w => w.id) }); expanded.value = true }
function addPythonExample() { const flowId = newId('flow'), variableId = newId('variable'); editor.mutate(p => { p.variables.push({ id: variableId, name: 'Python 换算温度', type: 'number', initial: 0 }); p.python ??= { runtimeId: '3.14.8-win_amd64', dependencyLock: [] }; const kinds = ['trigger.ui', 'assign', 'python', 'condition', 'variable.set', 'log']; const nodes = kinds.map((kind, i) => createNode(kind, { x: 40 + i * 240, y: 100 })); nodes[1]!.config = { path: 'payload.rawTemperature', value: { source: 'literal', value: 253 } }; nodes[2]!.config.code = 'def transform(msg):\n    import math\n    raw = float(msg["payload"]["rawTemperature"])\n    if not math.isfinite(raw):\n        raise ValueError("温度数据无效")\n    msg["payload"] = {"temperature": raw / 10}\n    return msg\n'; nodes[3]!.config = { left: { source: 'message', path: 'payload.temperature' }, operator: 'gte', right: { source: 'literal', value: 0 } }; nodes[4]!.config = { variableId, value: { source: 'message', path: 'payload.temperature' } }; p.flows.push({ id: flowId, name: 'Python 温度换算示例', enabled: true, timeoutMs: 30000, nodes, edges: nodes.slice(1).map((node, i) => ({ id: newId('edge'), source: nodes[i]!.id, target: node.id, sourcePort: nodes[i]!.kind === 'condition' ? 'true' : 'out', targetPort: 'in' })) }); const button = createWidget('button', 520, 620); button.props.text = 'Python 换算'; button.events.click = { kind: 'flow', flowId, entryNodeId: nodes[0]!.id }; const display = createWidget('number', 800, 600); display.props.text = '换算结果'; display.props.unit = '°C'; display.bindings.value = { source: 'variable', key: variableId }; editor.page.value.widgets.push(button, display) }); editor.flowId.value = flowId; workspace.value = 'flow'; menuOpen.value = false; notify('已添加 Python 换算示例；导入 Python 运行资源后可预览') }
function keydown(event: KeyboardEvent) { const target = event.composedPath()[0] as HTMLElement; if (event.key === 'Escape') { menuOpen.value = false; help.value = false }; if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 's') { event.preventDefault(); void perform(async () => { await saveProject() }); return }; if (target?.closest('input, textarea, select, [contenteditable="true"]') || runtime.running.value) return; if (event.ctrlKey || event.metaKey) { if (event.key.toLowerCase() === 'z') { event.preventDefault(); event.shiftKey ? editor.redo() : editor.undo() }; if (event.key.toLowerCase() === 'y') { event.preventDefault(); editor.redo() }; if (event.key.toLowerCase() === 'd' && workspace.value === 'design') { event.preventDefault(); editor.duplicateSelected() } } else if ((event.key === 'Delete' || event.key === 'Backspace') && workspace.value === 'design') { event.preventDefault(); editor.removeSelected() } }
function beforeUnload(event: BeforeUnloadEvent) { if (editor.dirty.value) { event.preventDefault(); event.returnValue = '' } }
onMounted(async () => { window.addEventListener('keydown', keydown); window.addEventListener('beforeunload', beforeUnload); if (desktop) { try { environment.value = await getEnvironment(); const initial = await call<Project>('get_initial_project'); editor.replace(parseProject(JSON.stringify(initial))); projectPath.value = environment.value.projectPath; if (initial.assets?.length) await refreshAssets(initial) } catch (error) { report(error) } } })
onBeforeUnmount(() => { window.removeEventListener('keydown', keydown); window.removeEventListener('beforeunload', beforeUnload); runtime.dispose(); if (toastTimeout) clearTimeout(toastTimeout) })
</script>

<template>
  <div class="studio-shell" @click="menuOpen = false"><header class="app-header"><div class="brand-mark"><Activity :size="21" :stroke-width="2.3" /></div><span class="brand-title">HMI <b>Studio</b></span><span class="header-divider" /><input class="project-title-input" aria-label="项目名称" :value="editor.project.value.name" :disabled="runtime.running.value" @change="editor.mutate(p => p.name = ($event.target as HTMLInputElement).value || '未命名项目')" /><span v-if="editor.dirty.value" class="unsaved-dot" title="有未保存修改" /><span class="project-platform">Windows x64</span><span class="spacer" /><span class="environment-indicator"><i :class="{ desktop }" />{{ desktop ? '桌面工作区' : '浏览器设计模式' }}</span><button class="icon-button help-button" title="使用帮助" @click="help = true"><CircleHelp :size="18" /></button></header>
    <nav class="command-bar"><div class="file-menu-host" @click.stop><FButton appearance="subtle" @click="menuOpen = !menuOpen">文件<ChevronDown :size="13" /></FButton><div v-if="menuOpen" class="file-menu"><button :disabled="runtime.running.value" @click="newProject"><FilePlus2 :size="16" />新建项目</button><button :disabled="runtime.running.value" @click="perform(openProject)"><FolderOpen :size="16" />打开项目</button><button @click="perform(async () => { await saveProject() })"><Save :size="16" />保存项目<kbd>Ctrl S</kbd></button><button @click="perform(async () => { await saveProject(true) })"><Copy :size="16" />另存为</button><hr /><button :disabled="!desktop || runtime.running.value" @click="perform(() => importResource('plugin'))"><Cable :size="16" />导入协议插件</button><button :disabled="!desktop || runtime.running.value" @click="perform(() => importResource('python'))"><Code2 :size="16" />导入 Python 运行资源</button><button :disabled="!desktop || runtime.running.value" @click="perform(() => importResource('dependencies'))"><Box :size="16" />导入 Python 依赖</button><button :disabled="!desktop || runtime.running.value" @click="perform(importAsset)"><Download :size="16" />导入图片或字体</button><hr /><button :disabled="runtime.running.value" @click="addPythonExample"><Workflow :size="16" />添加 Python 示例流程</button></div></div><button class="icon-button" title="打开项目" :disabled="runtime.running.value || pending" @click="perform(openProject)"><FolderOpen :size="18" /></button><button class="icon-button" title="保存项目 (Ctrl+S)" :disabled="pending" @click="perform(async () => { await saveProject() })"><Save :size="18" /></button><span class="toolbar-separator" /><button class="icon-button" title="撤销 (Ctrl+Z)" :disabled="!editor.past.value.length || runtime.running.value" @click="editor.undo"><Undo2 :size="18" /></button><button class="icon-button" title="重做 (Ctrl+Y)" :disabled="!editor.future.value.length || runtime.running.value" @click="editor.redo"><Redo2 :size="18" /></button><span class="toolbar-separator" /><button class="icon-button" title="复制控件 (Ctrl+D)" :disabled="!editor.selected.value.length || runtime.running.value || workspace !== 'design'" @click="editor.duplicateSelected"><Copy :size="17" /></button><button class="icon-button" title="删除控件" :disabled="!editor.selected.value.length || runtime.running.value || workspace !== 'design'" @click="editor.removeSelected"><Trash2 :size="17" /></button><button class="icon-button" title="左对齐" :disabled="editor.selected.value.length < 2 || runtime.running.value" @click="editor.align('left')"><ArrowLeftToLine :size="17" /></button><button class="icon-button" title="顶端对齐" :disabled="editor.selected.value.length < 2 || runtime.running.value" @click="editor.align('top')"><ArrowUpToLine :size="17" /></button><span class="spacer" /><FButton appearance="subtle" :disabled="pending || runtime.busy.value" @click="perform(check)"><ShieldCheck :size="16" />检查</FButton><FButton :appearance="runtime.running.value ? 'secondary' : 'primary'" :disabled="pending || runtime.busy.value" @click="perform(preview)"><SquareStop v-if="runtime.running.value" :size="16" /><Play v-else :size="16" />{{ runtime.busy.value ? '处理中…' : runtime.running.value ? '停止预览' : '预览运行' }}</FButton><FButton :disabled="pending || runtime.running.value || !desktop" @click="perform(exportProject)"><Download :size="16" />导出程序</FButton></nav>
    <div class="workspace-tabs"><button :class="{ active: workspace === 'design' }" :disabled="runtime.running.value" @click="workspace = 'design'"><AppWindow :size="16" />界面设计</button><button :class="{ active: workspace === 'flow' }" @click="workspace = 'flow'"><Workflow :size="16" />逻辑流程</button><button v-if="runtime.running.value" :class="{ active: workspace === 'preview' }" @click="workspace = 'preview'"><Play :size="15" />运行预览<span class="live-dot" /></button><span class="spacer" /><span v-if="runtime.running.value" class="workspace-hint">运行中 · 修改项目请先停止预览</span><span v-else class="workspace-hint">{{ workspace === 'design' ? '拖放控件，自由构建界面' : '连接节点，定义交互逻辑' }}</span></div>
    <div class="studio-workspace" :class="{ 'preview-workspace': workspace === 'preview' }"><template v-if="workspace === 'design'"><aside class="library"><div class="library-tabs"><button :class="{ active: activeLibrary === 'widgets' }" @click="activeLibrary = 'widgets'"><Grid2X2 :size="15" />组件</button><button :class="{ active: activeLibrary === 'layers' }" @click="activeLibrary = 'layers'"><Layers :size="15" />图层</button></div><div class="library-content"><template v-if="activeLibrary === 'widgets'"><div class="library-search"><Search :size="14" /><input v-model="paletteFilter" placeholder="搜索组件…" aria-label="搜索组件" /></div><div class="library-section-heading">基础组件</div><div class="widget-library"><button v-for="widget in filteredWidgets" :key="widget.kind" class="widget-library-item" draggable="true" @dragstart="($event as DragEvent).dataTransfer?.setData('application/hmi-widget', widget.kind)" @click="editor.addWidget(widget.kind)"><component :is="icons[widget.icon]" :size="20" :stroke-width="1.5" /><span>{{ widget.label }}</span></button></div><div class="library-section-heading">设备组件</div><button class="serial-library-item" draggable="true" @dragstart="($event as DragEvent).dataTransfer?.setData('application/hmi-widget', 'serial-panel')" @click="addSerialPanel()"><Cable :size="20" :stroke-width="1.5" /><span>串口控制面板<small>连接资源 + 控制按钮</small></span><Plus :size="14" /></button></template><div v-else class="layers-list"><div v-if="!editor.page.value.widgets.length" class="muted-copy">此页面暂无控件。</div><button v-for="widget in [...editor.page.value.widgets].sort((a,b) => b.zIndex - a.zIndex)" :key="widget.id" :class="{ active: editor.selected.value.includes(widget.id) }" @click="editor.selected.value = [widget.id]"><component :is="icons[widgetKinds.find(k => k.kind === widget.kind)?.icon ?? 'Square']" :size="15" />{{ widget.name }}</button></div></div><div class="pages-panel"><div class="panel-title">页面<button class="icon-button" title="添加页面" @click="addPage"><Plus :size="15" /></button></div><button v-for="page in editor.project.value.pages" :key="page.id" class="page-item" :class="{ active: editor.pageId.value === page.id }" @click="editor.pageId.value = page.id; editor.selected.value = []"><AppWindow :size="15" /><span>{{ page.name }}</span><span class="page-count">{{ page.widgets.length }}</span></button><button v-if="editor.project.value.pages.length > 1" class="text-button page-remove" @click="removePage"><Trash2 :size="12" />删除当前页面</button></div></aside><DesignCanvas :editor="editor" @serial-panel-drop="addSerialPanel" /><WidgetInspector :editor="editor" /></template><FlowEditor v-else-if="workspace === 'flow'" :editor="editor" :events="runtime.events.value" :running="runtime.running.value" @error="report" @run="(flowId, nodeId) => perform(async () => { await runtime.act({ kind: 'flow', flowId, entryNodeId: nodeId }) })" /><RuntimeView v-else-if="runtimeProject" :project="runtimeProject" :runtime="runtime" @error="report" /></div>
    <ResourcesPanel ref="resources" v-model:expanded="expanded" :editor="editor" :runtime="runtime" :issues="issues" @error="report" @import-plugin="perform(() => importResource('plugin'))" />
    <footer class="status-bar"><span class="status-ready"><i :class="{ running: runtime.running.value }" />{{ pending ? '正在处理…' : runtime.running.value ? '预览运行中' : '就绪' }}</span><span>{{ editor.project.value.pages.length }} 个页面</span><span>{{ editor.project.value.flows.length }} 个流程</span><span class="spacer" /><span v-if="editor.project.value.python">Python {{ environment?.pythonAvailable ? '已就绪' : '需导入运行资源' }}</span><span>{{ projectPath ? projectPath.split(/[\\/]/).pop() : '未保存到项目文件' }}</span><span>v{{ environment?.version ?? '0.1.0' }}</span></footer>
    <input ref="fileInput" type="file" accept=".json" hidden @change="browserOpen" />
    <div v-if="toast" class="toast" :class="{ error: toastError }" role="status"><CircleDot v-if="toastError" :size="18" /><Check v-else :size="18" /><span>{{ toast }}</span><button class="icon-button" title="关闭提示" @click="toast = ''"><X :size="14" /></button></div>
    <div v-if="help" class="modal-backdrop" @click.self="help = false"><section class="help-dialog" role="dialog" aria-modal="true" aria-label="开始使用"><div class="inline-between"><h2>开始搭建你的上位机</h2><button class="icon-button" title="关闭帮助" @click="help = false"><X :size="18" /></button></div><ol><li><strong>设计界面</strong><p>拖入控件，在右侧设置外观、数据绑定与事件。</p></li><li><strong>配置设备</strong><p>在底部添加串口连接，选择端口与协议。示例模拟设备可用于体验。</p></li><li><strong>编排流程</strong><p>添加界面事件入口，连接设备命令、条件、Python 代码和变量节点。</p></li><li><strong>预览与发布</strong><p>检查项目并预览。准备好本地运行模板与资源后，导出 Windows x64 程序。</p></li></ol><div class="help-note">Python 节点使用导入的 embeddable 资源，项目包含 Python 节点时才加入发布包。</div><FButton appearance="primary" @click="help = false">开始设计</FButton></section></div>
  </div>
</template>
